//! Cargo-driven `lunar.msstyles` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "___ImageBase", None),
        "x86_64" => ("x86_64-pc-windows-gnu", "__ImageBase", None),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "__ImageBase", None),
        o => panic!("lunar_msstyles-cargo: unsupported arch {o}"),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/media/themes/Lunar/lunar.msstyles",
        "media/themes/Lunar/lunar.msstyles",
        "@std",
        "sdk/lib/pseh/include",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &["WINVER=0x502", "_WIN32_WINNT=0x502"];

    Linker::new(target_json)
        .rc("media/themes/Lunar/lunar.msstyles/lunar.rc", rc_includes, rc_flags, rc_defines)
        // No code of its own: link nothing from rustc's bin (its panic
        // handler, i386's rsbegin/rsend), so the PE is cmake's.
        .shell_less()
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
